/**
 * How Kyoto chrysanthemum (`kyo-giku`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/kyo-giku";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Twenty-four petals spread between pairs of leaves. A curved band closes the space between the upper leaves, and the stalk meets a low foot with two small blades.","ja":"左右一対ずつの葉の間に二十四枚の花びらを広げます。上の葉の間は曲がった帯で閉じ、柄は二枚の小葉を添えた下の台につなぎます。"};

export default construction;
export { construction, description };
